"use strict";
const kioskMagazines=[
 {id:'manke',from:2006,name:'知音漫客',kind:'漫画',strap:'等下一期，比等下课还认真',about:'2006年创刊的中国原创漫画杂志。这里把等连载、交换杂志、猜下一话的阅读记忆收进报刊亭。',source:'https://www.ccct.net.cn/html/bqzs/2017/0512/232.html',memory:'刚拿到新一期，先把书包拉链拉好。课间才翻开，有人从后排探过头来，问这次更新了没有。借出去的时候约定不能折角，回来却多了一张画着人物的小纸条。故事讲到一半最磨人，也正因为没有立刻就能搜到的答案，下一次去报刊亭才显得格外重要。'},
 {id:'comicfans',from:2002,name:'漫友',kind:'漫画',strap:'书包里藏着的彩色世界',about:'动漫资讯与漫画阅读记忆。此处以2002年后的杂志体验为范围，不把1997年公司的起点直接当作同一刊物的发行日期。',source:'https://www.comicfans.net/',memory:'书摊上铺着一排彩色封面，你蹲下来挑了很久。最喜欢的不一定是最厚的一本，而是里面恰好有想看的访谈、画稿和推荐。回家把喜欢的页面夹上书签，隔一阵再翻，连旁边的小广告都记住了。'},
 {id:'rayli',from:1995,name:'瑞丽服饰美容',kind:'时尚写真',strap:'剪一页穿搭，夹进日记本',about:'瑞丽品牌创立于1995年。服饰、美容与日常搭配，让纸页上的造型变成周末逛街时的一点灵感。',source:'https://www.chlip.com.cn/about/rayli.php',memory:'窗边摊开一本杂志，先看鞋子，再看包，最后才发现原来一直喜欢的是那种干净的颜色。买不起整套搭配也没关系，衣柜里的旧衬衫换一种穿法，已经像是给周末换了心情。'},
 {id:'rayli-style',from:2000,name:'瑞丽伊人风尚',kind:'时尚写真',strap:'在纸页里练习长大的样子',about:'瑞丽系列的都市女性时尚刊物，2000年创办。关注服装、生活方式与个人风格。',source:'https://eladies.sina.com.cn/2004-08-26/106721.html',memory:'那时候看杂志，会偷偷想象自己第一次上班的模样。衣服要不要熨平，耳环会不会太显眼，包里应该装些什么。真正长大以后再回头，才发现怀念的是那份对未来细细打量的认真。'},
 {id:'xinwei',from:2001,name:'昕薇',kind:'时尚写真',strap:'妆发、街头与镜头里的笑容',about:'女性时尚月刊，2000年创办、2001年1月正式出版首刊；本亭从2001年展示。收录刊物线索，不把今天的内容伪装成旧期刊。',source:'https://bkso.baidu.com/item/昕薇/10381056',memory:'把刘海拨到另一边，对着镜子看了又看。杂志里说的小技巧不一定每次都成功，但和朋友围在一起讨论哪种颜色更好看，就足够消磨一个下午。拍照以后还要挑一张，存成手机的小小壁纸。'},
 {id:'elle',from:1988,name:'世界时装之苑 ELLE',kind:'时尚写真',strap:'报刊亭里的一扇时装橱窗',about:'1988年进入中国内地的时尚刊物。这里保留时装摄影与纸媒阅读的线索，官方页面可能包含今日内容。',source:'https://m.thepaper.cn/newsDetail_forward_29289312',memory:'从报刊亭经过，最先看见的是鲜亮的封面颜色。哪怕只站一小会儿，也会记住某件外套和某个笑容。纸张翻动的声音，比屏幕安静；喜欢一张照片的时候，能停留很久。'},
 {id:'fhm',from:2004,name:'男人装',kind:'时尚写真',strap:'人物、摄影与都市话题',about:'2004年在中国内地推出的男性综合时尚杂志。收录人物摄影、服饰及都市文化资料入口，不提供未经授权的整期扫描。',source:'https://www.mediasearch.cn/medium%2Cb0a7ca4d-b093-4d2f-82fe-12b0c873e530.htm',memory:'杂志摊的玻璃后面，摆着风格很不一样的刊物。有人看人物采访，有人看摄影和服装，也有人只是好奇封面背后的故事。把那种城市正在变快的感觉留在纸页里，过很多年再看，连排版都带着时代的口音。'},
 {id:'story',from:1963,name:'故事会',kind:'故事阅读',strap:'再看完这个故事，就关灯',about:'1963年创刊的故事刊物。民间故事、生活里的悬念与幽默，是许多人在车站、书摊和家中读书时的记忆。',source:'https://www.storychina.cn/',memory:'车还没有来，先在小卖部门口翻几页。故事开头是一件不起眼的小事，读着读着就想知道后来怎样了。有人喊上车，才发现自己一直站在原地。那张没能翻完的纸页，后来会在某个晚上忽然想起来。'},
 {id:'duzhe',from:1981,name:'读者',kind:'故事阅读',strap:'把喜欢的句子抄进摘抄本',about:'1981年创刊，早期名为《读者文摘》，1993年改为《读者》。这里从项目可选的1996年起采用现名。',source:'https://pdf.dfcfw.com/pdf/H2_AN201511300011613389_1.pdf',memory:'摘抄本上有不同颜色的笔迹，认真画过横线的句子旁边，还会标一个小小的星号。也许后来忘记了原来的文章，却记得某次晚自习后，自己怎样把一句话读了两遍。'},
 {id:'youth',from:1981,name:'青年文摘',kind:'故事阅读',strap:'从作文素材，读到自己的心事',about:'1981年创刊的青年文摘刊物。青春故事、阅读摘录和成长话题，常常与校园里的课外阅读一起出现。',source:'https://cpa.cbpt.cnki.net/WKE2/WebPublication/wkTextContent.aspx?contentID=98e117dd-358a-4ecc-a1bd-2f42be9e98ce',memory:'最初为了找作文素材，后来翻着翻着就忘了目的。窗外是操场，桌上是一支快没水的笔。看到像自己的心事，会把那一页折成很轻的一角，等晚上再读。'},
 {id:'yilin',from:2003,name:'意林',kind:'故事阅读',strap:'小小篇幅，装下一段午休',about:'2003年创刊的文摘刊物。这里呈现短篇阅读与校园书摊的回忆，不转载其受版权保护的原文。',source:'https://www.szlib.com/pdcn/Home/Content/22104',memory:'午休只剩十分钟，刚好还能读一篇。短故事里的路很远，教室里的阳光却慢慢从桌边移过去。合上杂志的时候，不一定得到什么道理，只是觉得今天还有一个值得记住的小片刻。'}
];
let kioskCategory='全部',kioskQuery='',kioskSelected=null;
function kioskAvailable(){return kioskMagazines.filter(m=>m.from<=Number(year()));}
function kioskVisible(){const q=kioskQuery.trim().toLowerCase();return kioskAvailable().filter(m=>(kioskCategory==='全部'||m.kind===kioskCategory)&&(!q||[m.name,m.kind,m.strap,m.about].join(' ').toLowerCase().includes(q)));}
function openMagazineKiosk(){kioskSelected=null;navigate({type:'magazines',name:'旧日报刊亭',url:'archaeo://magazines'});}
function kioskCard(m){const cover=kioskCover(m);return `<button class="kiosk-card" data-kiosk-item="${m.id}"><span class="kiosk-book ${m.kind==='漫画'?'comic':m.kind==='故事阅读'?'story':'fashion'}"><img class="kiosk-cover-image" src="${cover.image}" alt="${escapeHTML(m.name)}${cover.label}" loading="lazy"><small>${cover.label}</small><strong>${escapeHTML(m.name)}</strong><em>${escapeHTML(m.strap)}</em><b>${m.from} 起 · ${m.kind}</b></span><span>翻开回忆 &gt;&gt;</span></button>`;}
function renderMagazineKiosk(){const m=kioskAvailable().find(x=>x.id===kioskSelected);return `<section class="magazine-kiosk"><nav><button data-action="home">‹ 时光首页</button><button data-kiosk-open>报刊亭目录</button><button data-anime-club>动漫猜测楼</button><button data-poster-room>年代画报</button><button data-capture-view>保存这一页</button></nav><header><small>NEWSPAPER & MAGAZINE / ${year()}</small><h1>放学了，去报刊亭看看。</h1><p>漫画连载、时尚写真、故事文摘。找一本曾经舍不得合上的杂志。</p></header>${!m&&Number(year())>=2004?'<figure class="kiosk-scene"><img src="images/posters/newsstand.jpg" alt="原创怀旧报刊亭场景，非历史照片"><figcaption>原创怀旧场景 · AI辅助绘制 · 非历史报刊亭照片，图中刊物非原刊封面</figcaption></figure>':''}${m?`${renderKioskReading(m)}<details class="kiosk-about"><summary>刊物介绍与回忆</summary><article class="kiosk-detail"><div>${kioskCard(m)}</div><div><span>${m.kind} · ${m.from}年起</span><h2>${escapeHTML(m.name)}</h2><p>${escapeHTML(m.about)}</p><a href="${m.source}" target="_blank" rel="noopener noreferrer">刊物资料 / 官方阅读线索 ↗</a><h3>报刊亭旁的一段回忆</h3><p>${escapeHTML(m.memory)}</p><small>以上回忆为本站原创短文，不是该杂志原文。</small><div class="kiosk-next"><button data-memory-gallery>看美女壁纸与图文故事</button><button data-anime-club>去聊聊当年的动漫</button><button data-world-channel="books">去掌上书房读小说</button></div></div></article></details>`:`<form id="kiosk-search"><label for="kiosk-query">找一本杂志</label><input id="kiosk-query" maxlength="80" value="${escapeHTML(kioskQuery)}" placeholder="故事会 / 漫客 / 瑞丽 / 写真…"><button>查找</button></form><div class="kiosk-filters">${['全部','漫画','时尚写真','故事阅读'].map(k=>`<button data-kiosk-category="${k}" class="${kioskCategory===k?'selected':''}">${k}</button>`).join('')}</div><p>${year()} 年书架 · 找到 ${kioskVisible().length} 本</p><div class="kiosk-grid">${kioskVisible().map(kioskCard).join('')||'<p>这个年份还没有找到，换个关键词或年份再看看。</p>'}</div>${Number(year())<2006?'<aside>在找《知音漫客》？它从2006年开始出现。<button data-kiosk-2006>去2006年的报刊亭 →</button></aside>':''}`}<footer>刊物名称与相关权利属于各自权利人。部分封面为来源标注的真实刊物封面，其余为原创导览封面；不将后来的期刊内容当作当年的内页。外部资料可能包含今日信息。</footer></section>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-kiosk-open],[data-kiosk-item],[data-kiosk-category],[data-kiosk-2006]');if(!b)return;e.preventDefault();if(b.hasAttribute('data-kiosk-open'))return openMagazineKiosk();if(b.hasAttribute('data-kiosk-2006')){applyDate('2006'+date.slice(4));return openMagazineKiosk();}if(b.dataset.kioskItem&&kioskAvailable().some(m=>m.id===b.dataset.kioskItem)){kioskSelected=b.dataset.kioskItem;kioskReadId=null;kioskReadPage=0;}if(b.dataset.kioskCategory){kioskCategory=b.dataset.kioskCategory;kioskSelected=null;}navigate(current,false);});
document.addEventListener('submit',e=>{if(e.target.id!=='kiosk-search')return;e.preventDefault();kioskQuery=$('#kiosk-query').value.slice(0,80);kioskSelected=null;navigate(current,false);});
